using System;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Windows.Forms;
class CompactHeaderCheck {
 [STAThread] static int Main(){try{Application.EnableVisualStyles();var app=Assembly.LoadFrom(Path.GetFullPath("dist/BenchMarkX.exe"));var create=app.GetType("Overclock.StudioView").GetMethod("CreateCompactHeader",BindingFlags.Static|BindingFlags.NonPublic);foreach(int width in new[]{820,780,600,560}){var selector=(Control)Activator.CreateInstance(app.GetType("Overclock.DarkCombo"),true);((System.Collections.IList)selector.GetType().GetField("Items").GetValue(selector)).Add("HP 24f Display / DISPLAY1");selector.GetType().GetProperty("SelectedIndex").SetValue(selector,0,null);app.GetType("Overclock.Theme").GetMethod("Combo",BindingFlags.Static|BindingFlags.Public).Invoke(null,new object[]{selector});var refresh=(Button)Activator.CreateInstance(app.GetType("Overclock.ModernButton"),true);refresh.Text="Refresh";selector.Font=refresh.Font=new Font("Segoe UI",11);var hdr=(CheckBox)Activator.CreateInstance(app.GetType("Overclock.StudioCheckBox"),true);hdr.Enabled=false;hdr.Text="Enable HDR - HDR not supported";hdr.Font=new Font("Segoe UI",11);using(var row=(TableLayoutPanel)create.Invoke(null,new object[]{selector,refresh,hdr})){row.BackColor=Color.FromArgb(16,18,20);row.Size=new Size(width,44);row.CreateControl();for(int pass=0;pass<20;pass++){row.Width=width-pass%2*30;hdr.Text=pass%2==0?"Enable HDR - unavailable":"Enable HDR - HDR not supported";row.PerformLayout();var children=row.Controls.Cast<Control>().ToArray();for(int i=0;i<children.Length;i++){if(children[i].Right>row.Width||children[i].Left<0)throw new Exception("Header overflow");for(int j=i+1;j<children.Length;j++)if(children[i].Bounds.IntersectsWith(children[j].Bounds))throw new Exception("Header controls overlap");}}row.Width=width;row.PerformLayout();using(var bitmap=new Bitmap(width,44)){row.DrawToBitmap(bitmap,new Rectangle(0,0,width,44));bitmap.Save("tests/compact-header-"+width+"-fixture.png");}Console.WriteLine("PASS compact header at "+width+" px: 20 caption/resize cycles, no overlap or overflow");}}return 0;}catch(Exception error){Console.Error.WriteLine(error);return 1;}}
}
